"""Retry configuration consumed by the settlement engine."""

from typing import NamedTuple


class RetryPlan(NamedTuple):
    gateway_attempts: int
    worker_attempts: int


def retry_plan(repository):
    """Return total attempts under settlement policy effective 2026-10-16."""
    if repository == "clearing-adapter":
        return RetryPlan(gateway_attempts=3, worker_attempts=1)
    if repository in ("payment-worker", "reconciliation-worker"):
        return RetryPlan(gateway_attempts=1, worker_attempts=3)
    raise ValueError(f"Unknown repository: {repository!r}")
